import { FaHome, FaUser, FaCog, FaSignOutAlt } from 'react-icons/fa'; // Import icons from react-icons

const Sidebar = () => {
  return (
    <div className="sidebar">
      <ul>
        <li><a href="#dashboard"><FaHome /> Dashboard</a></li>
        <li><a href="#profile"><FaUser /> Profile</a></li>
        <li><a href="#settings"><FaCog /> Settings</a></li>
        <li><a href="#logout"><FaSignOutAlt /> Logout</a></li>
      </ul>
    </div>
  );
};

export default Sidebar;
